using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS",   Name = "Computer Science",        Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics",             Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Code = "PHYS", Name = "Physics",                 Description = "Exploration of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG",  Name = "English",                 Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 5, Code = "HIST", Name = "History",                 Description = "Study of past events, civilizations, and cultural developments." },
            new() { Id = 6, Code = "BIO",  Name = "Biology",                 Description = "Life sciences covering genetics, ecology, and molecular biology." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1,  DepartmentId = 1, CourseCode = "CS 101",   Title = "Introduction to Programming",   Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",  InstructorName = "Dr. Alice Chen",       InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory computer science. She holds a Ph.D. from MIT and has published extensively on CS education.",          IsFeatured = true },
            new() { Id = 2,  DepartmentId = 1, CourseCode = "CS 201",   Title = "Data Structures & Algorithms",  Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.",                                                          Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM",    InstructorName = "Dr. Robert Kim",       InstructorBio = "Dr. Kim specializes in algorithm design and competitive programming. He previously worked at Google Research before joining the faculty.",                            IsFeatured = true },
            new() { Id = 3,  DepartmentId = 1, CourseCode = "CS 310",   Title = "Database Systems",              Description = "Principles of database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.",                                                                                                       Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM",      InstructorName = "Prof. Maria Santos",   InstructorBio = "Prof. Santos brings 10 years of industry experience in data engineering from Oracle and Amazon before transitioning to academia." },
            new() { Id = 4,  DepartmentId = 1, CourseCode = "CS 450",   Title = "Machine Learning",              Description = "Introduction to supervised and unsupervised learning, neural networks, and practical applications using modern frameworks.",                                                                                                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM",      InstructorName = "Dr. Alice Chen",       InstructorBio = "Dr. Chen has over 15 years of experience teaching introductory computer science. She holds a Ph.D. from MIT and has published extensively on CS education.",          IsFeatured = true },

            // Mathematics
            new() { Id = 5,  DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I",                    Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",                                                                                                         Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. James Okafor",    InstructorBio = "Dr. Okafor is an award-winning educator who has taught calculus for 20 years. He is known for his engaging lecture style and clear explanations." },
            new() { Id = 6,  DepartmentId = 2, CourseCode = "MATH 240", Title = "Linear Algebra",                Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations with applications to data science and engineering.",                                                                                           Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM",     InstructorName = "Dr. Sarah Lin",        InstructorBio = "Dr. Lin's research focuses on numerical linear algebra. She received the departmental teaching excellence award three years running." },
            new() { Id = 7,  DepartmentId = 2, CourseCode = "MATH 301", Title = "Probability & Statistics",      Description = "Random variables, probability distributions, hypothesis testing, regression analysis, and Bayesian inference.",                                                                                                              Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", InstructorName = "Dr. James Okafor",    InstructorBio = "Dr. Okafor is an award-winning educator who has taught calculus for 20 years. He is known for his engaging lecture style and clear explanations.",                     IsFeatured = true },

            // Physics
            new() { Id = 8,  DepartmentId = 3, CourseCode = "PHYS 101", Title = "General Physics I",             Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.",                                                                                                                              Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Emily Novak",     InstructorBio = "Dr. Novak is a former NASA researcher who brings real-world space science examples into the classroom." },
            new() { Id = 9,  DepartmentId = 3, CourseCode = "PHYS 201", Title = "Electromagnetism",              Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Prerequisite: PHYS 101.",                                                                                                                 Credits = 4, Schedule = "Tue/Thu 2:00–3:15 PM",      InstructorName = "Dr. Emily Novak",     InstructorBio = "Dr. Novak is a former NASA researcher who brings real-world space science examples into the classroom.",                                                               IsFeatured = true },

            // English
            new() { Id = 10, DepartmentId = 4, CourseCode = "ENG 110",  Title = "College Writing",               Description = "Develop essential academic writing skills including argumentation, research methods, and rhetorical analysis.",                                                                                                               Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM",  InstructorName = "Prof. David Wright",   InstructorBio = "Prof. Wright is a published author and writing coach. He has helped thousands of students strengthen their academic and creative writing." },
            new() { Id = 11, DepartmentId = 4, CourseCode = "ENG 250",  Title = "American Literature",           Description = "Survey of major American literary works from the colonial period through the 21st century, exploring themes of identity, freedom, and social change.",                                                                       Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Lisa Hernandez",   InstructorBio = "Dr. Hernandez specializes in 20th-century American fiction and has authored two books on the Harlem Renaissance." },

            // History
            new() { Id = 12, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500",         Description = "Survey of world civilizations from prehistory through the late medieval period, covering Mesopotamia, Rome, China, and the Islamic Golden Age.",                                                                              Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM",     InstructorName = "Dr. Thomas Grant",     InstructorBio = "Dr. Grant is a medieval historian with extensive field experience in archaeological digs across Europe and the Middle East." },
            new() { Id = 13, DepartmentId = 5, CourseCode = "HIST 202", Title = "Modern European History",       Description = "European history from the Enlightenment through the Cold War, including the French Revolution, industrialization, and world wars.",                                                                                          Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM",      InstructorName = "Dr. Anna Petrov",      InstructorBio = "Dr. Petrov grew up in Prague and brings a unique Central European perspective to modern history. She is the author of three acclaimed history textbooks." },

            // Biology
            new() { Id = 14, DepartmentId = 6, CourseCode = "BIO 101",  Title = "Introduction to Biology",       Description = "Foundational biology covering cell structure, genetics, evolution, and ecology. Includes weekly lab sessions.",                                                                                                               Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM",  InstructorName = "Dr. Karen Osei",       InstructorBio = "Dr. Osei is a molecular biologist whose research on gene expression has been published in Nature and Science.",                                                        IsFeatured = true },
            new() { Id = 15, DepartmentId = 6, CourseCode = "BIO 320",  Title = "Genetics",                      Description = "Mendelian and molecular genetics, gene regulation, genomics, and applications in biotechnology and medicine.",                                                                                                              Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM",      InstructorName = "Dr. Karen Osei",       InstructorBio = "Dr. Osei is a molecular biologist whose research on gene expression has been published in Nature and Science." },
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

