{"file_text": "@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Request Enrollment</h1>
<p>Fill out the form below to submit your enrollment request. All fields marked with <span class="text-danger">*</span> are required.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@selectedCourseTitle</strong> has been received.</p>
        <hr />
        <p class="mb-0">You will receive a confirmation via your university email.</p>
    </div>
    <a href="/enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm" method="post">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
            <ValidationMessage For="() => Model.StudentName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU12345" />
            <ValidationMessage For="() => Model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="courseSelect" class="form-label">Course <span class="text-danger">*</span></label>
            <InputSelect id="courseSelect" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">— Select a course —</option>
                @foreach (var dept in Catalog.GetDepartments())
                {
                    <optgroup label="@dept.Name">
                        @foreach (var course in Catalog.GetCoursesByDepartment(dept.Id))
                        {
                            <option value="@course.Id">@course.CourseCode — @course.Title (@course.Credits cr)</option>
                        }
                    </optgroup>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="comments" class="form-label">Comments (optional)</label>
            <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
            <ValidationMessage For="() => Model.Comments" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = PreselectedCourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.CourseCode} — {course.Title}" : "Unknown";
        Catalog.SubmitEnrollment(Model);
        submitted = true;
    }
}
